                    this.setAttribute('data-sort-order', isAscending ? 'asc' : 'desc');

                    rows.forEach(row => {
                        const cell = row.querySelector(`td:nth-child(${Array.from(headers).indexOf(this) + 1})`);
                        const value = cell.textContent.trim();
                        const numericValue = isNaN(value) ? value.toLowerCase() : parseFloat(value);

                        rows.forEach(otherRow => {
                            const otherCell = otherRow.querySelector(`td:nth-child(${Array.from(headers).indexOf(this) + 1})`);
                            const otherValue = otherCell.textContent.trim();
                            const otherNumericValue = isNaN(otherValue) ? otherValue.toLowerCase() : parseFloat(otherValue);

                            if (isAscending) {
                                if (numericValue > otherNumericValue) {
                                    row.after(otherRow);
                                }
                            } else {
                                if (numericValue < otherNumericValue) {
                                    row.after(otherRow);
                                }
                            }
                        });
                    });
                });
            });
        });
    </script>
