malloc, calloc and realloc are the three most important functions in C. They are used to allocate memory dynamically.

malloc is used to allocate memory of a specific size.

calloc is used to allocate memory for an array of elements.

realloc is used to resize the memory block allocated by malloc or calloc.

Here is an example of how to implement these functions in C:

malloc:

#include <stdio.h>
#include <stdlib.h>
void* my_malloc(size_t size) {
void* ptr = malloc(size);
if (ptr == NULL) {
return NULL;
}
return ptr;
}
int main() {
int* arr = my_malloc(10 * sizeof(int));
if (arr == NULL) {
printf("Memory allocation failed\n");
return 1;
}
for (int i = 0; i < 10; i++) {
arr[i] = i;
}
for (int i = 0; i < 10; i++) {
printf("%d ", arr[i]);
}
free(arr);
return 0;
}

calloc:

#include <stdio.h>
#include <stdlib.h>
void* my_calloc(size_t num, size_t size) {
void* ptr = calloc(num, size);
if (ptr == NULL) {
return NULL;
}
return ptr;
}
int main() {
int* arr = my_calloc(10, sizeof(int));
if (arr == NULL) {
printf("Memory allocation failed\n");
return 1;
}
for (int i = 0; i < 10; i++) {
arr[i] = i;
}
for (int i = 0; i < 10; i++) {
printf("%d ", arr[i]);
}
free(arr);
return 0;
}

realloc:

#include <stdio.h>
#include <stdlib.h>
void* my_realloc(void* ptr, size_t size) {
void* new_ptr = realloc(ptr, size);
if (new_ptr == NULL) {
return NULL;
}
return new_ptr;
}
int main() {
int* arr = my_malloc(10 * sizeof(int));
if (arr == NULL) {
printf("Memory allocation failed\n");
return 1;
}
for (int i = 0; i < 10; i++) {
arr[i] = i;
}
for (int i = 0; i < 10; i++) {
printf("%d ", arr[i]);
}
arr = my_realloc(arr, 20 * sizeof(int));
if (arr == NULL) {
printf("Memory reallocation failed\n");
return 1;
}
for (int i = 10; i < 20; i++) {
arr[i] = i;
}
for (int i = 0; i < 20; i++) {
printf("%d ", arr[i]);
}
free(arr);
return 0;
}

