```javascript
const express = require('express');
const { Pool } = require('pg');
const cors = require('cors');
require('dotenv').config();

const app = express();
const port = 3000;

// Middleware
app.use(cors());
app.use(express.json());

// Database Connection
const pool = new Pool({
  user: process.env.DB_USER || 'postgres',
  host: process.env.DB_HOST || 'localhost',
  database: process.env.DB_NAME || 'hotels_db',
  password: process.env.DB_PASSWORD || 'password',
  port: process.env.DB_PORT || 5432,
});

// API Endpoint: /api/hotels
app.get('/api/hotels', async (req, res) => {
  const { q } = req.query; // The search query

  if (!q) {
    return res.status(400).json({ error: 'Query parameter "q" is required' });
  }

  try {
    // SQL Injection Prevention: We use parameterized queries
    const query = `
      SELECT id, name, city, country, rating 
      FROM hotels 
      WHERE name ILIKE $1 
      ORDER BY name 
      LIMIT 10
    `;

    const values = [`%${q}%`]; // ILIKE is case-insensitive

    const result = await pool.query(query, values);

    // Return only the necessary fields
    res.json(result.rows);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Server error' });
  }
});

app.listen(port, () => {
  console.log(`Server running on http://localhost:${port}`);
});
