        // 1. Establish a secure WebSocket connection
        // The URL is dynamic based on the region and protocol version
        const url = `wss://discord.com/api/v9`; 

        this.ws = new WebSocket(url);

        this.ws.on('open', () => {
            console.log('WebSocket connection established');
            this.authenticate();
        });

        this.ws.on('message', (data) => {
            this.handleIncomingPacket(data);
        });

